# Let's write a python function to compute confidence for both verifiable and conceptual claims under F0011 / F0012 / F0027 rules.

def calc_conceptual_confidence(coherence=0.70, scope=0.10, fruitfulness=0.10, consensus=0.05, refutability=0.05, dependencies_conf=[]):
    base = coherence + scope + fruitfulness + consensus + refutability
    base = min(base, 0.95) # cap at 0.95 per F0011

    # Apply dependency downgrades
    conf = base
    for d_conf in dependencies_conf:
        if d_conf < 0.95:
            conf *= d_conf

    return base, conf

def calc_verifiable_confidence(base_conf, refutation_vagueness=False, scope_overreach=False, unstated_assumption=False, dependencies_conf=[]):
    conf = base_conf
    if refutation_vagueness:
        conf *= 0.75
    if scope_overreach:
        conf *= 0.60
    if unstated_assumption:
        conf *= 0.80
    for d_conf in dependencies_conf:
        if d_conf < 0.95:
            conf *= d_conf
    return min(conf, 0.99) # capped at 0.99 for empirical/verifiable per F0025/F0026/F0027

# Test conceptual claim PHY-006 (QM interpretations)
# Base: coherence=0.70, scope=0.10, fruitfulness=0.10, consensus=0.00 (active debate), refutability=0.05 -> base 0.95
# Dependencies: F0011 (0.85), F0012 (0.90), F0026 (1.00)
base_006, conf_006 = calc_conceptual_confidence(consensus=0.00, dependencies_conf=[0.85, 0.90, 1.00])
print(f"PHY-006 conceptual confidence: base={base_006:.2f}, after deps={conf_006:.4f}")

# What if PHY-006 builds on F0026 (1.00) and F0035 (0.95)?
base_006_alt, conf_006_alt = calc_conceptual_confidence(consensus=0.00, dependencies_conf=[1.00, 0.95])
print(f"PHY-006 alt conceptual confidence: base={base_006_alt:.2f}, after deps={conf_006_alt:.4f}")

